update finance
create_id = #{createId}, update_id = #{updateId}, create_time = #{createTime}, update_time = #{updateTime}, iotype = #{iotype}, repay = #{repay}, bill_type = #{billType}, price = #{price}, remark = #{remark}, atta = #{atta}, status = #{status}, account = #{account}, field1 = #{field1}, field2 = #{field2}, field3 = #{field3}, field4 = #{field4}, field5 = #{field5}, field6 = #{field6}, selltype = #{selltype}, registeruser = #{registeruser}, from_name = #{fromName},
where id = #{id}

mapper.select:
select id,game_name,price,FROM_UNIXTIME(UNIX_TIMESTAMP(create_time) ,'%Y-%m-%d %h:%i:%s') as create_time
from finance
where del=0
and bill_type=#{billType}
and to_days(now())-to_days(create_time) = 0
and create_time  >=  #{createTime}

select
ROUND(IFNULL(s.totalKS,0),2) totalKS,
ROUND(IFNULL(s.totalPayPrice,0),2) totalPayPrice,
ROUND(IFNULL(s.totalPrice,0),2) totalPrice,
ROUND(IFNULL(s.totalYL,0) ,2)totalYL
from ( select
sum(case when iotype ='1' then price else 0 end) totalPayPrice,
sum(case when iotype ='2' then price else 0 end) totalPrice,
sum(case when iotype ='2' then field5 else 0 end) totalYL,
sum(case when iotype ='2' then field6 else 0 end) totalKS
from finance

    del = 0
    and create_id = #{createId}
    and update_id = #{updateId}
    and repay = #{repay}
    and bill_type = #{billType}
    and price = #{price}
    and atta = #{atta}
    and status = #{status}
    and account = #{account}
    and from_name = #{fromName}
    and (remark like '%${remark}%' or field1 like '%${remark}%' or
        field2 like
        '%${remark}%' or field3 like '%${remark}%' or field4 like '%${remark}%' or field5 like '%${remark}%' or
        field6
        like '%${remark}%' or price like '%${remark}%')

    and registeruser like '%${registeruser}%'
    and create_time>#{startCreateTime}
    and create_time<#{endCreateTime}

)s

select
    case when ISNULL(from_name) then '空渠道' else from_name end as fromName
    ,count(1)  count
    ,sum(price)  totalPrice
    from finance

    and create_time >#{startCreateTime}
    and #{endCreateTime}> create_time
    and status = #{status}
     and iotype = #{iotype}
     and create_id = #{createId}

    GROUP BY fromName
    order by totalPrice desc
